package tn.utm.fst.gestionpresence.nativeapp.data.remote

import android.util.Base64
import io.ktor.client.HttpClient
import io.ktor.client.engine.okhttp.OkHttp
import io.ktor.client.plugins.contentnegotiation.ContentNegotiation
import io.ktor.client.request.*
import io.ktor.client.statement.HttpResponse
import io.ktor.client.statement.bodyAsText
import io.ktor.http.*
import io.ktor.serialization.kotlinx.json.json
import kotlinx.serialization.json.*
import tn.utm.fst.gestionpresence.nativeapp.BuildConfig
import tn.utm.fst.gestionpresence.nativeapp.core.model.*
import java.time.Instant

class OnlineApiClient(private val baseUrl:String=BuildConfig.SUPABASE_URL,private val publishableKey:String=BuildConfig.SUPABASE_PUBLISHABLE_KEY){
 private val json=Json{ignoreUnknownKeys=true;explicitNulls=false};private val http=HttpClient(OkHttp){expectSuccess=false;install(ContentNegotiation){json(json)}}
 suspend fun login(identifier:String,credential:String):AuthSession{val b=http.post("$baseUrl/functions/v1/pin-login"){publicHeaders();contentType(ContentType.Application.Json);setBody(buildJsonObject{put("identifier",identifier.trim().lowercase());put("credential",credential)})}.requireObject();val access=b.requiredString("access_token");return AuthSession(access,b.requiredString("refresh_token"),b.string("user_id")?:jwtClaim(access,"sub")?:throw ApiException("UNAUTHENTICATED","Session invalide."),b.string("role")?:"teacher",false,Instant.now().epochSecond+(b.long("expires_in")?:3600))}
 suspend fun refresh(refreshToken:String):AuthSession{val b=http.post("$baseUrl/auth/v1/token"){publicHeaders();parameter("grant_type","refresh_token");contentType(ContentType.Application.Json);setBody(buildJsonObject{put("refresh_token",refreshToken)})}.requireObject();val a=b.requiredString("access_token");return AuthSession(a,b.string("refresh_token")?:refreshToken,b["user"]?.let{(it as? JsonObject)?.string("id")}?:jwtClaim(a,"sub")?:throw ApiException("UNAUTHENTICATED","Session invalide."),jwtClaim(a,"user_role")?:jwtClaim(a,"role")?:"teacher",false,Instant.now().epochSecond+(b.long("expires_in")?:3600))}
 suspend fun logout(s:AuthSession){http.post("$baseUrl/auth/v1/logout"){authenticatedHeaders(s)}}
 suspend fun profile(s:AuthSession):UserProfile{val r=http.get("$baseUrl/rest/v1/profiles"){authenticatedHeaders(s);parameter("id","eq.${s.userId}");parameter("select","id,email,username,full_name,role,account_state,mfa_required")};val b=r.requireSingleObject();return UserProfile(b.requiredString("id"),b.string("email"),b.string("username"),b.string("full_name")?:"Enseignant",b.string("role")?:"teacher",b.string("account_state")?:"active",false)}
 suspend fun appContract(s:AuthSession):AppContract{val b=rpc(s,"get_app_contract",buildJsonObject{}).jsonObject;val m=b["maintenance"] as? JsonObject?:JsonObject(emptyMap());val v=b["minimum_client_versions"] as? JsonObject?:JsonObject(emptyMap());return AppContract(b.int("schema_version")?:2,b.string("academic_year")?:"2026/2027",m.boolean("enabled")?:false,m.string("message")?:"",v.string("web"),v.string("windows"),v.string("android"),false)}
 suspend fun classes(s:AuthSession)=getArray(s,"classes","*").map{val r=it.jsonObject;AcademicClass(r.requiredString("id"),r.requiredString("teacher_id"),r.requiredString("name"),r.string("module")?:"",r.string("track"),r.int("class_number"),r.int("group_number"),r.string("day"),r.string("start_time")?.take(5),r.string("end_time")?.take(5),r.string("room"),r.long("revision")?:1)}.sortedBy{it.name}
 suspend fun students(s:AuthSession)=getArray(s,"students","*").map{val r=it.jsonObject;Student(r.requiredString("id"),r.requiredString("teacher_id"),r.requiredString("class_id"),r.requiredString("last_name"),r.requiredString("first_name"),r.string("email"),r.long("revision")?:1)}.sortedWith(compareBy<Student>{it.lastName}.thenBy{it.firstName})
 suspend fun sessions(s:AuthSession)=getArray(s,"sessions","*").map{val r=it.jsonObject;TeachingSession(r.requiredString("id"),r.requiredString("teacher_id"),r.requiredString("class_id"),r.requiredString("session_date"),r.requiredString("start_time").take(5),r.requiredString("end_time").take(5),r.string("completed_at"),r.long("revision")?:1)}.sortedWith(compareByDescending<TeachingSession>{it.sessionDate}.thenBy{it.startTime})
 suspend fun attendance(s:AuthSession)=getArray(s,"attendance","*").map{attendanceRecord(it.jsonObject)}
 suspend fun teacherDirectory(s:AuthSession)=rpc(s,"teacher_directory_v2",buildJsonObject{}).jsonArray.map{val r=it.jsonObject;TeacherDirectoryEntry(r.requiredString("teacher_id"),r.string("teacher_name")?:"Enseignant",r.string("day"),r.string("start_time")?.take(5),r.string("end_time")?.take(5),r.string("track"),r.int("class_number"),r.int("group_number"),r.string("module"),r.string("room"))}
 suspend fun upsertClass(s:AuthSession,row:JsonObject)=upsert(s,"classes",row);suspend fun upsertStudent(s:AuthSession,row:JsonObject)=upsert(s,"students",row);suspend fun upsertSession(s:AuthSession,row:JsonObject)=upsert(s,"sessions",row)
 suspend fun deleteRow(s:AuthSession,table:String,id:String){http.delete("$baseUrl/rest/v1/$table"){authenticatedHeaders(s);parameter("id","eq.$id")}.requireSuccess()}
 suspend fun getAttendanceSheet(s:AuthSession,sessionId:String):AttendanceSheet{val b=rpc(s,"get_attendance_sheet",buildJsonObject{put("p_session_id",sessionId)}).jsonObject;ensureBusinessResult(b);return AttendanceSheet(sessionId,b.string("sheet_id"),b.long("revision")?:0,(b["records"] as? JsonArray).orEmpty().map{attendanceRecord(it.jsonObject,sessionId)})}
 suspend fun saveAttendanceSheet(s:AuthSession,sessionId:String,expectedRevision:Long,operationId:String,records:List<AttendanceDraft>,justification:String?=null):AttendanceSheet{val b=rpc(s,"save_attendance_sheet",buildJsonObject{put("p_session_id",sessionId);put("p_expected_revision",expectedRevision);put("p_operation_id",operationId);put("p_records",buildJsonArray{records.forEach{r->add(buildJsonObject{put("student_id",r.studentId);put("status",r.status.wireValue);put("comment",r.comment);if(r.grade==null)put("grade",JsonNull)else put("grade",r.grade)})}});if(justification==null)put("p_justification",JsonNull)else put("p_justification",justification)}).jsonObject;ensureBusinessResult(b);return AttendanceSheet(sessionId,b.string("sheet_id"),b.long("revision")?:expectedRevision,(b["records"] as? JsonArray).orEmpty().map{attendanceRecord(it.jsonObject,sessionId)})}
 suspend fun mfaFactors(s:AuthSession):List<MfaFactor>=emptyList();suspend fun enrollMfa(s:AuthSession):MfaEnrollment=throw ApiException("FORBIDDEN","La double authentification est désactivée.");suspend fun verifyMfa(s:AuthSession,factorId:String,code:String)=s;suspend fun unenrollMfa(s:AuthSession,factorId:String){}
 suspend fun adminAction(s:AuthSession,body:JsonObject)=http.post("$baseUrl/functions/v1/admin-teacher"){authenticatedHeaders(s);contentType(ContentType.Application.Json);setBody(body)}.requireObject();fun assuranceLevel(s:AuthSession)="aal1"
 private suspend fun getArray(s:AuthSession,t:String,select:String)=http.get("$baseUrl/rest/v1/$t"){authenticatedHeaders(s);parameter("select",select);parameter("deleted_at","is.null")}.requireJson().jsonArray
 private suspend fun upsert(s:AuthSession,t:String,row:JsonObject){http.post("$baseUrl/rest/v1/$t"){authenticatedHeaders(s);header("Prefer","resolution=merge-duplicates,return=minimal");contentType(ContentType.Application.Json);setBody(JsonArray(listOf(row)))}.requireSuccess()}
 private suspend fun rpc(s:AuthSession,f:String,b:JsonObject)=http.post("$baseUrl/rest/v1/rpc/$f"){authenticatedHeaders(s);contentType(ContentType.Application.Json);setBody(b)}.requireJson()
 private fun HttpRequestBuilder.publicHeaders(){header("apikey",publishableKey)};private fun HttpRequestBuilder.authenticatedHeaders(s:AuthSession){publicHeaders();header(HttpHeaders.Authorization,"Bearer ${s.accessToken}")}
 private suspend fun HttpResponse.requireSuccess(){if(!status.isSuccess())throw toApiException()};private suspend fun HttpResponse.requireJson():JsonElement{val p=runCatching{json.parseToJsonElement(bodyAsText().ifBlank{"{}"})}.getOrElse{JsonObject(emptyMap())};if(!status.isSuccess())throw toApiException(p);return p};private suspend fun HttpResponse.requireObject()=requireJson().jsonObject
 private suspend fun HttpResponse.requireSingleObject():JsonObject=when(val v=requireJson()){is JsonObject->v;is JsonArray->v.singleOrNull() as? JsonObject?:throw ApiException("VALIDATION_ERROR","Réponse serveur invalide.");else->throw ApiException("VALIDATION_ERROR","Réponse serveur invalide.")}
 private suspend fun HttpResponse.toApiException(parsed:JsonElement?=null):ApiException{val b=(parsed?:runCatching{json.parseToJsonElement(bodyAsText().ifBlank{"{}"})}.getOrNull()) as? JsonObject;val c=b?.string("code")?:when(status){HttpStatusCode.Unauthorized->"UNAUTHENTICATED";HttpStatusCode.Forbidden->"FORBIDDEN";HttpStatusCode.TooManyRequests->"RATE_LIMITED";in HttpStatusCode.InternalServerError..HttpStatusCode.GatewayTimeout->"SERVER_UNAVAILABLE";else->"VALIDATION_ERROR"};return ApiException(c,b?.string("message")?:b?.string("error")?:"Requête invalide.",b?.string("correlation_id"),status.value)}
 private fun ensureBusinessResult(b:JsonObject){if(b.boolean("ok")!=true)throw ApiException(b.string("code")?:"INTERNAL_ERROR",b.string("message")?:b.string("error")?:"Opération refusée.",b.string("correlation_id"))};private fun attendanceRecord(r:JsonObject,f:String?=null)=AttendanceRecord(r.requiredString("id"),r.string("session_id")?:f.orEmpty(),r.requiredString("student_id"),AttendanceStatus.fromWire(r.string("status")),r.string("comment")?:"",r.double("grade"),r.long("revision")?:1,r.string("updated_at"));private fun jwtClaim(jwt:String,key:String)=runCatching{val e=jwt.split('.')[1].replace('-','+').replace('_','/');val p=e+"=".repeat((4-e.length%4)%4);json.parseToJsonElement(Base64.decode(p,Base64.NO_WRAP).decodeToString()).jsonObject.string(key)}.getOrNull()
}
private fun JsonObject.string(k:String)=this[k]?.takeUnless{it is JsonNull}?.jsonPrimitive?.contentOrNull;private fun JsonObject.requiredString(k:String)=string(k)?:throw ApiException("VALIDATION_ERROR","Champ serveur manquant: $k");private fun JsonObject.boolean(k:String)=string(k)?.toBooleanStrictOrNull();private fun JsonObject.int(k:String)=this[k]?.jsonPrimitive?.intOrNull;private fun JsonObject.long(k:String)=this[k]?.jsonPrimitive?.longOrNull;private fun JsonObject.double(k:String)=this[k]?.takeUnless{it is JsonNull}?.jsonPrimitive?.doubleOrNull
